<script>
document.addEventListener('DOMContentLoaded', () => {
 const tabs=document.querySelectorAll('[data-tour-tab]'), panels=document.querySelectorAll('[data-tour-panel]'); tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(x=>x.classList.remove('is-active'));panels.forEach(x=>x.classList.remove('is-active'));tab.classList.add('is-active');document.querySelector(`[data-tour-panel="${tab.dataset.tourTab}"]`).classList.add('is-active')}));
 const category=document.getElementById('tour-category'), subcategory=document.getElementById('tour-subcategory'); category?.addEventListener('change',async()=>{subcategory.innerHTML='<option value="">Loading...</option>';const r=await fetch(`{{ route('admin.tours.subcategories') }}?category_id=${category.value}`);const items=await r.json();subcategory.innerHTML='<option value="">No subcategory</option>'+items.map(i=>`<option value="${i.id}">${i.name}</option>`).join('')});
 const templates={itinerary:'<div class="wmt-repeater-row" data-row><button type="button" data-remove-row>×</button><input placeholder="Step title"><input type="number" placeholder="Duration"><select><option>Unit</option><option>minutes</option><option>hours</option><option>days</option></select><input placeholder="Icon"><textarea placeholder="Step description"></textarea></div>',package:'<div class="wmt-repeater-row wmt-package-row" data-row><button type="button" data-remove-row>×</button><input placeholder="Package name"><textarea placeholder="Package description"></textarea><label>Live <input type="checkbox" checked></label></div>',price:'<div class="wmt-repeater-row" data-row><button type="button" data-remove-row>×</button><input type="number" placeholder="Package #"><select><option value="shared">Shared vehicle</option><option value="private">Private vehicle</option></select><input type="number" placeholder="Adult price"><input type="number" placeholder="Child price"><input type="number" placeholder="Min guests"><input type="number" placeholder="Max guests"></div>',availability:'<div class="wmt-repeater-row" data-row><button type="button" data-remove-row>×</button><input type="date"><input type="time"><input type="number" placeholder="Capacity"><input type="number" placeholder="Cutoff hrs"><label>Blocked <input type="checkbox"></label></div>'};
 const fieldNames={itinerary:['title','duration','duration_unit','icon','description'],package:['name','description','is_active'],price:['package_index','vehicle_type','adult_price','child_price','minimum_guests','maximum_guests'],availability:['available_date','start_time','capacity','booking_cutoff_hours','is_blocked']};
 document.querySelectorAll('[data-add-row]').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.addRow, holder=document.getElementById(`${type}-rows`), index=holder.querySelectorAll('[data-row]').length, wrap=document.createElement('div');wrap.innerHTML=templates[type];const row=wrap.firstElementChild;row.querySelectorAll('input,select,textarea').forEach((input,i)=>{input.name=`${type==='itinerary'?'itineraries':type+'s'}[${index}][${fieldNames[type][i]}]`;if(input.type==='checkbox')input.value='1'});holder.append(row)}));
 document.addEventListener('click',e=>{if(e.target.matches('[data-remove-row]'))e.target.closest('[data-row]').remove()});
});
</script>
@endsection
